ctx,cancel:=context.WithDeadline(context.Background(),time.Now().Add(-2*time.Millisecond));defer cancel()
    if e:=WaitForCancel(ctx);e!=ctx.Err()||e!=context.DeadlineExceeded{t.Fatal(e)}
}
